// Browser-only QA for the synthetic HTML generated by verify-visual-system.mjs.
// Reuse the browser launched by agent-browser. No authentication or network mutation.
import assert from 'node:assert/strict';
import { readdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const [directory, endpoint] = process.argv.slice(2);
assert.ok(directory && path.basename(directory).startsWith('billetera-visual-'), 'Expected isolated visual fixture directory');
const url = new URL(endpoint);
assert.ok(url.protocol === 'ws:' && ['127.0.0.1', 'localhost'].includes(url.hostname), 'Only local browser CDP is supported');
const socket = new WebSocket(endpoint);
await new Promise((resolve, reject) => { socket.addEventListener('open', resolve, { once: true }); socket.addEventListener('error', reject, { once: true }); });
let sequence = 0;
const pending = new Map();
socket.addEventListener('message', ({ data }) => {
  const response = JSON.parse(data);
  if (!response.id) return;
  const promise = pending.get(response.id); if (!promise) return;
  pending.delete(response.id);
  if (response.error) promise.reject(new Error(response.error.message)); else promise.resolve(response.result);
});
function send(method, params = {}, sessionId) {
  const id = ++sequence;
  return new Promise((resolve, reject) => { pending.set(id, { resolve, reject }); socket.send(JSON.stringify({ id, method, params, ...(sessionId ? { sessionId } : {}) })); });
}
const targets = await send('Target.getTargets');
const target = targets.targetInfos.find((entry) => entry.type === 'page' && entry.url.includes('billetera-visual-'));
assert.ok(target, 'Open a visual fixture using agent-browser first');
const { sessionId } = await send('Target.attachToTarget', { targetId: target.targetId, flatten: true });
async function evaluate(expression) {
  const result = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }, sessionId);
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.text);
  return result.result.value;
}
const files = (await readdir(directory)).filter((file) => file.endsWith('.html'));
const failures = [];
let checks = 0;
try {
  await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] }, sessionId);
  for (const width of [390, 768, 1024, 1280, 1440]) {
    await send('Emulation.setDeviceMetricsOverride', { width, height: 1000, deviceScaleFactor: 1, mobile: false }, sessionId);
    for (const file of files) {
      await send('Page.navigate', { url: pathToFileURL(path.join(directory, file)).href }, sessionId);
      let loaded = false;
      for (let attempt = 0; attempt < 20; attempt++) {
        loaded = await evaluate(`location.href.endsWith(${JSON.stringify(file)}) && document.readyState === 'complete' && !!document.querySelector('h1')`);
        if (loaded) break;
        await new Promise((resolve) => setTimeout(resolve, 50));
      }
      assert.ok(loaded, file + ' loads');
      // Check both resting pages and expanded actions; form controls must not create overflow.
      for (const expanded of [false, true]) {
        await evaluate(`document.querySelectorAll('.action-disclosure').forEach(d => d.open=${expanded})`);
        const measurement = await evaluate(`({width:innerWidth,scroll:document.documentElement.scrollWidth,heading:!!document.querySelector('h1'),aside:document.querySelector('.document-aside')?.getBoundingClientRect().width,errors:!!document.querySelector('[data-nextjs-dialog]'),unlabelled:Array.from(document.querySelectorAll('input:not([type="hidden"]),select,textarea')).filter(e=>!e.closest('label')&&!e.labels?.length&&!e.getAttribute('aria-label')).map(e=>e.name||e.id||e.tagName)})`);
        if (measurement.scroll > measurement.width + 1 || measurement.errors || measurement.unlabelled.length) failures.push({ file, width, expanded, ...measurement });
        checks++;
      }
      await evaluate(`document.querySelectorAll('.action-disclosure').forEach(d => d.open=false)`);
      if ((width === 390 || width === 1280) && !file.includes('nuevo') && !file.includes('nueva')) {
        const image = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false }, sessionId);
        await writeFile(path.join(directory, file.replace('.html', '-' + width + '.png')), Buffer.from(image.data, 'base64'));
      }
    }
  }
  console.log(JSON.stringify({ pages: files.length, widths: [390, 768, 1024, 1280, 1440], checks, failures }, null, 2));
  assert.equal(failures.length, 0, 'Visual overflow / labeling check');
} finally { socket.close(); }
